}

function SlotsMotionFromContext({
  inputRef,
  children,
}: Omit<SlotsMotionProps, 'slots'>) {
  const { slots } = React.use(OTPInputContext);
  return (
    <SlotsMotion slots={slots} inputRef={inputRef}>
